"""Exercise real durable producers and n8n callbacks in the disposable clone."""

def producer_cases():
    created=py("n6=Native('http://web:8080',keys['20'],6);w=n6.call('/api/v3/work_packages','POST',{'subject':'PRODUCER_CLONE_'+str(uuid.uuid4()),c['source_field']:'PRODUCER-CLONE-'+str(uuid.uuid4()),'description':{'raw':'Producer controlled source for exact citation.'},'_links':{'project':{'href':'/api/v3/projects/6'},'type':{'href':'/api/v3/types/1'}}});print(json.dumps({'id':w['id']}))")
    identifier=created['id']
    setup=("from gateway.service import Service\nfrom gateway.engineering import scoped_service\n"
           "from gateway.native_incremental import scan\nfrom gateway import integration_events as ie\n"
           "s=Service(Store(root),c,'/tmp/producer-workspace');sc=scoped_service(s,6)\n")
    scan_result=py(setup+f"scan(sc,20,authority='machine')\nie.publish(sc.store)\nwith sc.store.connect() as d:\n rows=d.execute(\"SELECT id,document FROM integration_event_outbox WHERE json_extract(document,'$.kind')='NATIVE_CHANGED' AND json_extract(document,'$.payload.native_id')=?\",({identifier},)).fetchall()\n assert len(rows)==1\n print(json.dumps({{'event_id':rows[0]['id']}}))")
    def deliver(kind,event_id):
        return py(setup+f"event_id={event_id!r}\nwith sc.store.connect() as d:\n delayed=[(r['id'],r['next_at']) for r in d.execute(\"SELECT id,next_at FROM integration_event_outbox WHERE id!=? AND state IN ('PENDING','RETRY','SENDING')\",(event_id,))]\n d.executemany('UPDATE integration_event_outbox SET next_at=? WHERE id=?',[(time.time()+3600,i) for i,_ in delayed])\ntry: delivery=ie.deliver_pending(sc)\nfinally:\n with sc.store.connect() as d:d.executemany('UPDATE integration_event_outbox SET next_at=? WHERE id=?',[(at,i) for i,at in delayed])\nwith sc.store.connect() as d:\n row=d.execute('SELECT o.state,r.document,r.execution_id FROM integration_event_outbox o JOIN integration_event_receipts r ON r.id=o.id WHERE o.id=?',(event_id,)).fetchone()\n assert row and delivery=='ACKED' and row['state']=='ACKED'\n ack=json.loads(row['document']);assert ack['business_result']['state']\n print(json.dumps({{'kind':{kind!r},'state':ack['business_result']['state'],'event_id':event_id,'execution_id':row['execution_id']}}))")
    wf02=deliver('NATIVE_CHANGED',scan_result['event_id']);assert wf02['state']=='SOURCE_OBSERVED'
    failure=py(setup+f"from unittest.mock import patch\nwith sc.store.connect() as d:d.execute(\"UPDATE knowledge_sync SET next_at=? WHERE native_id!=?\",(time.time()+3600,{identifier}))\nwith patch.object(Service,'sync_canonical_native',side_effect=RuntimeError('CLONE_TRANSIENT_VECTOR_OUTAGE')):sc.process_knowledge_sync()\nie.publish(sc.store)\nwith sc.store.connect() as d:\n rows=d.execute(\"SELECT id FROM integration_event_outbox WHERE json_extract(document,'$.kind')='INDEX_FAILED' AND json_extract(document,'$.payload.native_id')=? ORDER BY rowid DESC\",({identifier},)).fetchall()\n assert rows\n print(json.dumps({{'event_id':rows[0]['id']}}))")
    wf14=deliver('INDEX_FAILED',failure['event_id']);assert wf14['state']=='WAITING_RETRY'
    verified=py(setup+f"with sc.store.connect() as d:d.execute('UPDATE knowledge_sync SET next_at=0 WHERE native_id=?',({identifier},))\nfor _ in range(3):\n sc.process_knowledge_sync()\n with sc.store.connect() as d:row=d.execute(\"SELECT id FROM knowledge_sync WHERE native_id=? AND state='verified' ORDER BY rowid DESC LIMIT 1\",({identifier},)).fetchone()\n if row:break\nassert row\nie.publish(sc.store)\nwith sc.store.connect() as d:\n rows=d.execute(\"SELECT id FROM integration_event_outbox WHERE json_extract(document,'$.kind')='INDEX_VERIFIED' AND json_extract(document,'$.payload.native_id')=? ORDER BY rowid DESC\",({identifier},)).fetchall()\n assert rows\n print(json.dumps({{'event_id':rows[0]['id']}}))")
    wf13=deliver('INDEX_VERIFIED',verified['event_id']);assert wf13['state']=='INDEX_VERIFIED'
    reconcile=py(setup+"ie.publish(sc.store)\nwith sc.store.connect() as d:\n row=d.execute(\"SELECT id FROM integration_event_outbox WHERE json_extract(document,'$.kind')='RECONCILE_REQUESTED' AND state='PENDING' ORDER BY rowid DESC LIMIT 1\").fetchone()\n assert row\n print(json.dumps({'event_id':row['id']}))")
    wf15=deliver('RECONCILE_REQUESTED',reconcile['event_id']);assert wf15['state'] in {'RECONCILED','REPAIR_QUEUED','DRIFT_OBSERVED'}
    return {'native_id':identifier,'actual_delivery':[wf02,wf14,wf13,wf15],'outage':'injected once in disposable worker; expedited next_at only in clone','main_native_writes':0}


record('DURABLE_PRODUCERS','Native scan and real publish/deliver/receipt through WF02, WF14, WF13 and WF15',producer_cases)
